  `user_id` bigint(20) NOT NULL COMMENT '求职者ID',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态：0-待查看 1-已查看 2-感兴趣 3-不合适',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `apply_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '投递时间',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(4) DEFAULT '0' COMMENT '逻辑删除',
  `viewed_at` datetime DEFAULT NULL COMMENT '查看时间',
  `viewed_by` bigint(20) DEFAULT NULL COMMENT '查看人ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_resume` (`job_id`,`resume_id`),
  KEY `resume_id` (`resume_id`),
  KEY `idx_job_id` (`job_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_company_id` (`company_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=12821 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='投递记录表';
