--
-- Table structure for table `company_info`
--

DROP TABLE IF EXISTS `company_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `company_info` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '关联用户ID',
  `company_name` varchar(100) NOT NULL COMMENT '企业名称',
  `industry` varchar(50) DEFAULT NULL COMMENT '所属行业',
  `scale` varchar(50) DEFAULT NULL COMMENT '企业规模',
  `address` varchar(200) DEFAULT NULL COMMENT '企业地址',
  `description` text COMMENT '企业简介',
  `logo_url` varchar(200) DEFAULT NULL COMMENT 'Logo地址',
  `website` varchar(100) DEFAULT NULL COMMENT '企业官网',
  `contact_name` varchar(50) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系人电话',
  `contact_email` varchar(100) DEFAULT NULL COMMENT '联系人邮箱',
  `status` tinyint(4) DEFAULT '0' COMMENT '审核状态：0-待审核 1-已通过 2-已拒绝',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '拒绝原因',
  `pending_company_name` varchar(100) DEFAULT NULL COMMENT 'pending company name',
  `pending_industry` varchar(50) DEFAULT NULL COMMENT 'pending industry',
  `pending_scale` varchar(50) DEFAULT NULL COMMENT 'pending scale',
  `pending_address` varchar(200) DEFAULT NULL COMMENT 'pending address',
  `pending_description` text COMMENT 'pending description',
  `pending_logo_url` varchar(200) DEFAULT NULL COMMENT 'pending logo url',
  `pending_website` varchar(100) DEFAULT NULL COMMENT 'pending website',
  `pending_contact_name` varchar(50) DEFAULT NULL COMMENT 'pending contact name',
  `pending_contact_phone` varchar(20) DEFAULT NULL COMMENT 'pending contact phone',
  `pending_contact_email` varchar(100) DEFAULT NULL COMMENT 'pending contact email',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(4) DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

