--
-- Table structure for table `interview_rounds`
--

DROP TABLE IF EXISTS `interview_rounds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `interview_rounds` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'primary id',
  `application_id` bigint(20) NOT NULL COMMENT 'application id',
  `round_no` int(11) NOT NULL COMMENT 'interview round number',
  `interview_type` varchar(20) DEFAULT 'online' COMMENT 'interview type',
  `interview_time` datetime DEFAULT NULL COMMENT 'interview time',
  `location` varchar(200) DEFAULT NULL COMMENT 'interview location',
  `meeting_link` varchar(255) DEFAULT NULL COMMENT 'online meeting link',
  `contact_person` varchar(50) DEFAULT NULL COMMENT 'contact person',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT 'contact phone',
  `result` tinyint(4) DEFAULT '0' COMMENT 'result: 0 pending, 1 pass, 2 fail, 3 cancel',
  `notes` text COMMENT 'interview notes',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'create time',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'update time',
  `deleted` tinyint(4) DEFAULT '0' COMMENT 'deleted flag',
  `confirmation_status` tinyint(4) DEFAULT '0',
  `candidate_response_time` datetime DEFAULT NULL,
  `reschedule_time` datetime DEFAULT NULL,
