--
-- Table structure for table `job_info`
--

DROP TABLE IF EXISTS `job_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_info` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `title` varchar(100) NOT NULL COMMENT '职位标题',
  `category` varchar(50) DEFAULT NULL COMMENT '职位类别',
  `salary_min` int(11) DEFAULT NULL COMMENT '最低薪资',
  `salary_max` int(11) DEFAULT NULL COMMENT '最高薪资',
  `salary_month` int(11) DEFAULT '12' COMMENT '薪资月数',
  `work_city` varchar(50) DEFAULT NULL COMMENT '工作城市',
  `work_address` varchar(200) DEFAULT NULL COMMENT '工作地址',
  `experience` varchar(50) DEFAULT NULL COMMENT '经验要求',
  `education` varchar(50) DEFAULT NULL COMMENT '学历要求',
  `job_type` tinyint(4) DEFAULT '1' COMMENT '工作类型：1-全职 2-兼职 3-实习',
  `job_desc` text COMMENT '职位描述',
  `requirements` text COMMENT '岗位要求',
  `welfare` text COMMENT '福利待遇',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态：0-待审核 1-已发布 2-已拒绝 3-已下线',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '拒绝原因',
  `view_count` int(11) DEFAULT '0' COMMENT '浏览次数',
  `apply_count` int(11) DEFAULT '0' COMMENT '投递次数',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `deadline` date DEFAULT NULL COMMENT '截止日期',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(4) DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_company_id` (`company_id`),
  KEY `idx_status` (`status`),
  KEY `idx_category` (`category`),
  KEY `idx_work_city` (`work_city`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2551 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='招聘信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

