--
-- Table structure for table `offers`
--

DROP TABLE IF EXISTS `offers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `offers` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'primary id',
  `application_id` bigint(20) NOT NULL COMMENT 'application id',
  `status` tinyint(4) DEFAULT '0' COMMENT 'status: 0 pending, 1 accepted, 2 rejected, 3 expired',
  `offer_title` varchar(120) DEFAULT NULL COMMENT 'offer title',
  `salary_min` int(11) DEFAULT NULL COMMENT 'salary min',
  `salary_max` int(11) DEFAULT NULL COMMENT 'salary max',
  `benefits` text COMMENT 'benefits',
  `work_location` varchar(120) DEFAULT NULL COMMENT 'work location',
  `offer_content` text COMMENT 'offer content',
  `entry_date` date DEFAULT NULL COMMENT 'entry date',
  `expire_time` datetime DEFAULT NULL COMMENT 'offer expire time',
  `response_time` datetime DEFAULT NULL COMMENT 'candidate response time',
  `response_comment` text COMMENT 'candidate response comment',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'create time',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'update time',
  `deleted` tinyint(4) DEFAULT '0' COMMENT 'deleted flag',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_application_id` (`application_id`),
  KEY `idx_status` (`status`),
  CONSTRAINT `offers_ibfk_1` FOREIGN KEY (`application_id`) REFERENCES `application` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='offer and onboarding';
/*!40101 SET character_set_client = @saved_cs_client */;

