--
-- Table structure for table `resume`
--

DROP TABLE IF EXISTS `resume`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resume` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `real_name` varchar(50) DEFAULT NULL COMMENT '姓名',
  `gender` tinyint(4) DEFAULT NULL COMMENT '性别：0-女 1-男',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `phone` varchar(20) DEFAULT NULL COMMENT '电话',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `education` varchar(50) DEFAULT NULL COMMENT '最高学历',
  `school` varchar(100) DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `graduation_year` int(11) DEFAULT NULL COMMENT '毕业年份',
  `work_experience` text COMMENT '工作经历',
  `project_exp` text COMMENT '项目经验',
  `self_eval` text COMMENT '自我评价',
  `skills` text COMMENT '技能特长',
  `expected_city` varchar(50) DEFAULT NULL COMMENT '期望城市',
  `expected_salary_min` int(11) DEFAULT NULL COMMENT '期望最低薪资',
  `expected_salary_max` int(11) DEFAULT NULL COMMENT '期望最高薪资',
  `attachment_url` varchar(200) DEFAULT NULL COMMENT '简历附件',
  `avatar_url` varchar(200) DEFAULT NULL COMMENT '个人照片URL',
  `pdf_url` varchar(200) DEFAULT NULL COMMENT 'PDF简历URL',
  `is_default` tinyint(4) DEFAULT '1' COMMENT '是否默认简历：0-否 1-是',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(4) DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8400 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='简历表';
/*!40101 SET character_set_client = @saved_cs_client */;

